// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 fundAmount, uint256 withdrawAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= fundAmount);
        vm.assume(withdrawAmount <= fundAmount);
        try c.sendMoney(address(c), fundAmount) {} catch { return; }
        uint256 countBefore;
        try c.depositsCount() returns (uint256 __r) { countBefore = __r; } catch { return; }
        try c.withdraw(withdrawAmount) {} catch { return; }
        assertTrue(c.depositsCount() == countBefore);
    }

    function testFuzz_run(uint256 fundAmount, uint256 withdrawAmount) public {
        _run(fundAmount, withdrawAmount);
    }

    receive() external payable {}
}
